export function AdminTemplatesTestAll($$$DATA$$$ = {}, systemData = {}) {
    const {App, View, __base__, __layout__, __page__, __component__, __template__, __context__, __partial__, __system__, __env = {}, __helper = {}} = systemData;
    const __VIEW_PATH__ = 'admin.templates.test-all';
    const __VIEW_ID__ = $$$DATA$$$.__SSR_VIEW_ID__ || App.View.generateViewId();
    const __VIEW_TYPE__ = 'view';
    const cpparts = __VIEW_PATH__.split('.');
    cpparts.pop();  // Remove view name
    const __VIEW_NAMESPACE__ = cpparts.length > 0 ? cpparts.join('.') + '.' : '';
    // this is the wrapper element
    
    const __WRAPPER_ELEMENT__ = document.createElement('template');
    const __REFS__ = [];
    const self = new View.Engine(__VIEW_PATH__);
    const __STATE__ = self.__.states;



    self.setApp(App);


    const parseRefs = (frag) => {
        for (let i = 0; i < frag.childNodes.length; i++) {
            const node = frag.childNodes[i];
            __REFS__.push(node);
        }
    }
    const createHtml = (template) => {
        try {
            __WRAPPER_ELEMENT__.innerHTML = template;
        } catch (error) {
            console.error(error);
            __WRAPPER_ELEMENT__.innerHTML = '';
        }
        let frag = __WRAPPER_ELEMENT__.content;
        parseRefs(frag);
        return frag;
    }
    
    /**
     * 
     * @param {*} value 
     * @returns {[any, function, string]}
     */
    const useState = (value) => {
        return __STATE__.__useState(value);
    };
    const updateRealState = (state) => {
        __STATE__.__.updateRealState(state);
    };

    const lockUpdateRealState = () => {
        __STATE__.__.lockUpdateRealState();
    };
    const updateStateByKey = (key, state) => {
        __STATE__.__.updateStateByKey(key, state);
    };

    if(typeof $$$DATA$$$.__SSR_VIEW_ID__ !== 'undefined'){
        delete $$$DATA$$$.__SSR_VIEW_ID__;
    }
    const __UPDATE_DATA_TRAIT__ = {};
    let title = 'Test Page';
    const VERSION = '2.0';
    let {temp} = $$$DATA$$$;
    __UPDATE_DATA_TRAIT__.title = value => title = value;
    __UPDATE_DATA_TRAIT__.temp = value => temp = value;
    const __VARIABLE_LIST__ = ["title", "temp"];
    const set$isOpen = __STATE__.__.register('isOpen');
    let isOpen = null;
    const setIsOpen = (state) => {
        isOpen = state;
        set$isOpen(state);
    };
    __STATE__.__.setters.setIsOpen = setIsOpen;
    __STATE__.__.setters.isOpen = setIsOpen;
    const update$isOpen = (value) => {
        if(__STATE__.__.canUpdateStateByKey){
            updateStateByKey('isOpen', value);
            isOpen = value;
        }
    };
    const set$items = __STATE__.__.register('items');
    let items = null;
    const setItems = (state) => {
        items = state;
        set$items(state);
    };
    __STATE__.__.setters.setItems = setItems;
    __STATE__.__.setters.items = setItems;
    const update$items = (value) => {
        if(__STATE__.__.canUpdateStateByKey){
            updateStateByKey('items', value);
            items = value;
        }
    };

    self.setup('admin.templates.test-all', {}, {
        superView: null,
        hasSuperView: false,
        viewType: 'view',
        sections: {},
        wrapperConfig: { enable: false, tag: null, subscribe: true, attributes: {} },
        __props__: ["__WRAPPER_ELEMENT__", "createHtml", "__REFS__", "parseRefs"],
            __WRAPPER_ELEMENT__: __WRAPPER_ELEMENT__,
            refs: __REFS__,
            parseRefs: parseRefs,
            createHtml: createHtml,
        hasAwaitData: false,
        hasFetchData: false,
        subscribe: true,
        fetch: null,
        data: $$$DATA$$$,
        viewId: __VIEW_ID__,
        path: __VIEW_PATH__,
        usesVars: true,
        hasSections: false,
        hasSectionPreload: false,
        hasPrerender: false,
        renderLongSections: [],
        renderSections: [],
        prerenderSections: [],
        scripts: [],
        styles: [],
        resources: [],
        commitConstructorData: function() {
            // Then update states from data
            update$isOpen(false);
            update$items([]);
            // Finally lock state updates
            lockUpdateRealState();
        },
        updateVariableData: function(data) {
            // Update all variables first
            for (const key in data) {
                if (data.hasOwnProperty(key)) {
                    // Call updateVariableItemData directly from config
                    if (typeof this.config.updateVariableItemData === 'function') {
                        this.config.updateVariableItemData.call(this, key, data[key]);
                    }
                }
            }
            // Then update states from data
            update$isOpen(false);
            update$items([]);
            // Finally lock state updates
            lockUpdateRealState();
        },
        updateVariableItemData: function(key, value) {
            this.data[key] = value;
            if (typeof __UPDATE_DATA_TRAIT__[key] === "function") {
                __UPDATE_DATA_TRAIT__[key](value);
            }
        },
        prerender: function() {
    return null;
},
        render: function() {
                
    let __outputRenderedContent__ = '';
            try {
                __outputRenderedContent__ = `





<div class="comprehensive-test">
<h1>${App.View.escString(title)} - v${App.View.escString(VERSION)}</h1>
<p>Status: ${this.__reactive(`rc-${App.View.escString(__VIEW_ID__)}-5`, ['isOpen'], (__rc__) => isOpen ? 'Open' : 'Closed', {type: 'output', escapeHTML: true})}</p>

${this.__watch(`${__VIEW_ID__}-watch-1`, ['isOpen'], () => { if(isOpen){ return `
<div class="content">Content is visible</div>
`; } else if(title){ return `
<div>Has title</div>
`; } else { return `
<div>Default</div>
`; }
return '';
})}

${this.__for('increment', 0, 3, (__loop) => {
let __forOutputContent__ = ``;
for (let i = 0; i < 3; i++) {__loop.setCurrentTimes(i);
__forOutputContent__ += `<div>Loop ${App.View.escString(i)}</div>`;

}
return __forOutputContent__;
})
}

${this.__watch(`${__VIEW_ID__}-watch-2`, [], () => this.__foreach(["a", "b", "c"], (value, key, __loopIndex, __loop) => `
<div>${App.View.escString(key)}: ${App.View.escString(value)}</div>
`))}

${this.__watch(`${__VIEW_ID__}-watch-3`, ['isOpen'], () => {
let __switchOutputContent__ = '';
switch(isOpen) {

case true:
__switchOutputContent__ += `
<p>Case: Open</p>
`;
break;

case false:
__switchOutputContent__ += `
<p>Case: Closed</p>
`;
break;

default:
__switchOutputContent__ += `
<p>Default case</p>
`;
}
return __switchOutputContent__;
})}

<button ${this.__addEventConfig("click", [(event) => setIsOpen(!isOpen)])}>Toggle</button>
</div>`;
            } catch(e) {
                __outputRenderedContent__ = this.__showError(e.message);
                console.warn(e);
            }
            return __outputRenderedContent__;
            }
    });
    return self;
        }