export function AdminPagesFetch($$$DATA$$$ = {}, systemData = {}) {
    const {App, View, __base__, __layout__, __page__, __component__, __template__, __context__, __partial__, __system__, __env = {}, __helper = {}} = systemData;
    const __VIEW_PATH__ = 'admin.pages.fetch';
    const __VIEW_ID__ = $$$DATA$$$.__SSR_VIEW_ID__ || App.View.generateViewId();
    const __VIEW_TYPE__ = 'view';
    const cpparts = __VIEW_PATH__.split('.');
    cpparts.pop();  // Remove view name
    const __VIEW_NAMESPACE__ = cpparts.length > 0 ? cpparts.join('.') + '.' : '';
    // this is the wrapper element
    
    const __WRAPPER_ELEMENT__ = document.createElement('template');
    const __REFS__ = [];
    const self = new View.Engine(__VIEW_PATH__);
    const __STATE__ = self.__.states;



    self.setApp(App);


    const parseRefs = (frag) => {
        for (let i = 0; i < frag.childNodes.length; i++) {
            const node = frag.childNodes[i];
            __REFS__.push(node);
        }
    }
    const createHtml = (template) => {
        try {
            __WRAPPER_ELEMENT__.innerHTML = template;
        } catch (error) {
            console.error(error);
            __WRAPPER_ELEMENT__.innerHTML = '';
        }
        let frag = __WRAPPER_ELEMENT__.content;
        parseRefs(frag);
        return frag;
    }
    
    /**
     * 
     * @param {*} value 
     * @returns {[any, function, string]}
     */
    const useState = (value) => {
        return __STATE__.__useState(value);
    };
    const updateRealState = (state) => {
        __STATE__.__.updateRealState(state);
    };

    const lockUpdateRealState = () => {
        __STATE__.__.lockUpdateRealState();
    };
    const updateStateByKey = (key, state) => {
        __STATE__.__.updateStateByKey(key, state);
    };

    if(typeof $$$DATA$$$.__SSR_VIEW_ID__ !== 'undefined'){
        delete $$$DATA$$$.__SSR_VIEW_ID__;
    }
    const __UPDATE_DATA_TRAIT__ = {};
    const __VARIABLE_LIST__ = [];
    const set$users = __STATE__.__.register('users');
    let users = null;
    const setUsers = (state) => {
        users = state;
        set$users(state);
    };
    __STATE__.__.setters.setUsers = setUsers;
    __STATE__.__.setters.users = setUsers;
    const update$users = (value) => {
        if(__STATE__.__.canUpdateStateByKey){
            updateStateByKey('users', value);
            users = value;
        }
    };
    const set$isLoading = __STATE__.__.register('isLoading');
    let isLoading = null;
    const setIsLoading = (state) => {
        isLoading = state;
        set$isLoading(state);
    };
    __STATE__.__.setters.setIsLoading = setIsLoading;
    __STATE__.__.setters.isLoading = setIsLoading;
    const update$isLoading = (value) => {
        if(__STATE__.__.canUpdateStateByKey){
            updateStateByKey('isLoading', value);
            isLoading = value;
        }
    };
    const set$error = __STATE__.__.register('error');
    let error = null;
    const setError = (state) => {
        error = state;
        set$error(state);
    };
    __STATE__.__.setters.setError = setError;
    __STATE__.__.setters.error = setError;
    const update$error = (value) => {
        if(__STATE__.__.canUpdateStateByKey){
            updateStateByKey('error', value);
            error = value;
        }
    };

    self.setup('admin.pages.fetch', {}, {
        superView: View.execute(() => `${__layout__+'base'}`),
        hasSuperView: true,
        viewType: 'view',
        sections: {
        "meta:title":{
            "type":"short",
            "preloader":false,
            "useVars":false,
            "script":{}
        },
        "content":{
            "type":"long",
            "preloader":false,
            "useVars":false,
            "script":{}
        }
    },
        wrapperConfig: { enable: false, tag: null, subscribe: true, attributes: {} },
        __props__: ["__WRAPPER_ELEMENT__", "createHtml", "__REFS__", "parseRefs"],
            __WRAPPER_ELEMENT__: __WRAPPER_ELEMENT__,
            refs: __REFS__,
            parseRefs: parseRefs,
            createHtml: createHtml,
        hasAwaitData: false,
        hasFetchData: false,
        subscribe: true,
        fetch: null,
        data: $$$DATA$$$,
        viewId: __VIEW_ID__,
        path: __VIEW_PATH__,
        usesVars: false,
        hasSections: true,
        hasSectionPreload: false,
        hasPrerender: false,
        renderLongSections: ["content"],
        renderSections: ["meta:title"],
        prerenderSections: [],
        scripts: [],
        styles: [],
        resources: [],
        commitConstructorData: function() {
            // Then update states from data
            update$users([]);
            update$isLoading(true);
            update$error(null);
            // Finally lock state updates
            lockUpdateRealState();
        },
        updateVariableData: function(data) {
            // Update all variables first
            for (const key in data) {
                if (data.hasOwnProperty(key)) {
                    // Call updateVariableItemData directly from config
                    if (typeof this.config.updateVariableItemData === 'function') {
                        this.config.updateVariableItemData.call(this, key, data[key]);
                    }
                }
            }
            // Then update states from data
            update$users([]);
            update$isLoading(true);
            update$error(null);
            // Finally lock state updates
            lockUpdateRealState();
        },
        updateVariableItemData: function(key, value) {
            this.data[key] = value;
            if (typeof __UPDATE_DATA_TRAIT__[key] === "function") {
                __UPDATE_DATA_TRAIT__[key](value);
            }
        },
        prerender: function() {
    return null;
},
        render: function() {
                
    let __outputRenderedContent__ = '';
            try {
                __outputRenderedContent__ = `


${this.__section('meta:title', 'Demo Fetch Users', 'string')}
${this.__block('content', {}, `<div class="container py-5">
<h1 class="mb-4">Fetch Users Demo</h1>

${this.__watch(`${__VIEW_ID__}-watch-1`, ['isLoading'], () => { if(isLoading){ return `
<div class="alert alert-info">Đang tải users...</div>
`; } else if(error){ return `
<div class="alert alert-danger">Error: ${this.__reactive(`rc-${App.View.escString(__VIEW_ID__)}-9`, ['error'], (__rc__) => error, {type: 'output', escapeHTML: true})}</div>
`; } else if(!users || App.Helper.count(users) === 0){ return `
<div class="alert alert-danger">Error không có users</div>
`; } else { return `
${this.__watch(`${__VIEW_ID__}-watch-2`, ['users'], () => this.__foreach(users, (user, __loopKey, __loopIndex, __loop) => `
<div class="user-card mb-3 p-3 border rounded">
<h6>${App.View.escString(user['name'])}</h6>
<p class="mb-1">${App.View.escString(user['email'])}</p>
<small class="text-muted">${App.View.escString(user['company']['name'])}</small>
</div>
`))}
`; }
return '';
})}
</div>`)}`;
            } catch(e) {
                __outputRenderedContent__ = this.__showError(e.message);
                console.warn(e);
            }
            this.superViewPath = View.execute(() => `${__layout__+'base'}`);
            return this.__extends(this.superViewPath);
            }
    });
    return self;
        }